styles.css:
@font-face{font-family:"Noto Sans KR";src:url("assets/fonts/NotoSansKR.ttf") format("truetype");font-weight:100 900;font-style:normal;font-display:swap;}
:root {
  --color-ivory: #F9F6F1;
  --color-terracotta: #C27C5A;
  --color-charcoal: #2D2D2D;
  --color-charcoal-light: #4A4A4A;
  --color-bg: #FFFFFF;
  --color-border: #E5E0D8;
  --color-text-secondary: #666666;

  --font-body: 'Noto Sans KR', sans-serif;
  --font-display: 'Noto Sans KR', sans-serif;

  --space-xs: 8px;
  --space-sm: 12px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 48px;
  --space-xxl: 64px;

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;

  --max-width: 1120px;
}

body {
  margin: 0;
  padding: 0;
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.5;
  font-weight: 500;
  color: var(--color-charcoal);
  background-color: var(--color-ivory);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.masthead {
  padding: var(--space-xl) var(--space-lg);
  text-align: center;
  background-color: var(--color-ivory);
}

.masthead h1 {
  font-family: var(--font-display);
  font-size: 36px;
  line-height: 1.2;
  font-weight: 700;
  margin: 0 0 var(--space-xs) 0;
  color: var(--color-charcoal);
}

.subtitle {
  font-size: 18px;
  color: var(--color-charcoal-light);
  margin: 0;
  font-weight: 500;
}

main {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.editorial-hero {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-xl);
  align-items: center;
  min-height: 400px;
  margin-bottom: var(--space-xxl);
  background-color: var(--color-bg);
  border-radius: var(--radius-lg);
  overflow: hidden;
  padding: var(--space-xl);
}

.pottery-illustration {
  width: 100%;
  height: 100%;
  min-height: 300px;
  background-color: #F2EBE3;
  border-radius: var(--radius-md);
  position: relative;
}

.pottery-illustration::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 60%;
  height: 60%;
  border-radius: 50%;
  background-color: #E8DFD3;
  box-shadow: inset 0 10px 20px rgba(0,0,0,0.05);
}

.pottery-illustration::after {
  content: '';
  position: absolute;
  top: 40%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 40%;
  height: 40%;
  border-radius: 40% 40% 10% 10%;
  background-color: #D6CBB9;
}

.hero-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.hero-content h2 {
  font-family: var(--font-display);
  font-size: 36px;
  line-height: 1.2;
  font-weight: 700;
  margin: 0 0 var(--space-md) 0;
  color: var(--color-charcoal);
}

.hero-content p {
  font-size: 18px;
  color: var(--color-text-secondary);
  margin: 0;
  font-weight: 500;
}

.search-section {
  margin-bottom: var(--space-xl);
  position: relative;
}

.search-section label {
  display: none;
}

#search {
  width: 100%;
  padding: var(--space-md) var(--space-lg);
  font-size: 16px;
  font-family: var(--font-body);
  font-weight: 500;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background-color: var(--color-bg);
  color: var(--color-charcoal);
  box-sizing: border-box;
}

#search:focus {
  outline: none;
  border-color: var(--color-terracotta);
  box-shadow: 0 0 0 3px rgba(194, 124, 90, 0.1);
}

#search::placeholder {
  color: #A0A0A0;
}

.catalogue {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
  margin-bottom: var(--space-xxl);
}

.catalogue-card {
  background-color: var(--color-bg);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  display: flex;
  flex-direction: column;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.catalogue-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 20px rgba(0,0,0,0.05);
}

.card-illustration {
  height: 160px;
  background-color: #F2EBE3;
  border-radius: var(--radius-md);
  margin-bottom: var(--space-md);
  position: relative;
}

.card-illustration::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 50%;
  height: 50%;
  border-radius: 50%;
  background-color: #E8DFD3;
}

.catalogue-card h3 {
  font-family: var(--font-display);
  font-size: 20px;
  line-height: 1.3;
  font-weight: 700;
  margin: 0 0 var(--space-xs) 0;
  color: var(--color-charcoal);
}

.card-category {
  display: inline-block;
  font-size: 14px;
  font-weight: 600;
  color: var(--color-terracotta);
  background-color: rgba(194, 124, 90, 0.1);
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  margin-bottom: var(--space-sm);
}

.card-description {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin: 0 0 var(--space-md) 0;
  line-height: 1.6;
  flex-grow: 1;
}

.card-meta {
  display: flex;
  gap: var(--space-sm);
  font-size: 14px;
  color: var(--color-charcoal-light);
  margin-bottom: var(--space-md);
}

.card-price {
  font-size: 20px;
  font-weight: 700;
  color: var(--color-charcoal);
  margin-bottom: var(--space-md);
}

.btn-detail {
  width: 100%;
  padding: var(--space-sm) var(--space-md);
  background-color: transparent;
  border: 1px solid var(--color-terracotta);
  color: var(--color-terracotta);
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 600;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background-color 0.2s ease, color 0.2s ease;
}

.btn-detail:hover {
  background-color: var(--color-terracotta);
  color: var(--color-bg);
}

.btn-detail:focus {
  outline: none;
  box-shadow: 0 0 0 3px rgba(194, 124, 90, 0.2);
}

.empty-state {
  grid-column: 1 / -1;
  text-align: center;
  padding: var(--space-xxl);
  color: var(--color-text-secondary);
  font-size: 16px;
}

.booking-section {
  background-color: var(--color-bg);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  margin-bottom: var(--space-xxl);
}

.booking-section h2 {
  font-family: var(--font-display);
  font-size: 24px;
  line-height: 1.3;
  font-weight: 700;
  margin: 0 0 var(--space-lg) 0;
  color: var(--color-charcoal);
}

#selected-class-info {
  background-color: #F9F6F1;
  padding: var(--space-md);
  border-radius: var(--radius-md);
  margin-bottom: var(--space-lg);
}

#selected-class-info h3 {
  font-size: 18px;
  font-weight: 700;
  margin: 0 0 var(--space-xs) 0;
}

#selected-class-info p {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin: 0 0 var(--space-xs) 0;
}

.selected-price {
  font-weight: 700 !important;
  color: var(--color-charcoal) !important;
  margin-top: var(--space-sm) !important;
}

.form-group {
  margin-bottom: var(--space-md);
}

.form-group label {
  display: block;
  font-size: 14px;
  font-weight: 600;
  color: var(--color-charcoal-light);
  margin-bottom: var(--space-xs);
}

#guest, #date {
  width: 100%;
  padding: var(--space-sm) var(--space-md);
  font-size: 16px;
  font-family: var(--font-body);
  font-weight: 500;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background-color: var(--color-bg);
  color: var(--color-charcoal);
  box-sizing: border-box;
}

#guest:focus, #date:focus {
  outline: none;
  border-color: var(--color-terracotta);
  box-shadow: 0 0 0 3px rgba(194, 124, 90, 0.1);
}

#slot {
  width: 100%;
  padding: var(--space-sm) var(--space-md);
  font-size: 16px;
  font-family: var(--font-body);
  font-weight: 500;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background-color: var(--color-bg);
  color: var(--color-charcoal);
  box-sizing: border-box;
}

#slot:focus {
  outline: none;
  border-color: var(--color-terracotta);
  box-shadow: 0 0 0 3px rgba(194, 124, 90, 0.1);
}

.btn-primary {
  width: 100%;
  padding: var(--space-md) var(--space-lg);
  background-color: var(--color-charcoal);
  color: var(--color-bg);
  font-family: var(--font-body);
  font-size: 16px;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  margin-top: var(--space-sm);
}

.btn-primary:hover {
  background-color: #1A1A1A;
}

.btn-primary:focus {
  outline: none;
  box-shadow: 0 0 0 3px rgba(45, 45, 45, 0.2);
}

#confirmation {
  background-color: var(--color-bg);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  margin-bottom: var(--space-xxl);
}

#confirmation h2 {
  font-family: var(--font-display);
  font-size: 24px;
  line-height: 1.3;
  font-weight: 700;
  margin: 0 0 var(--space-lg) 0;
  color: var(--color-charcoal);
}

.confirm-row {
  display: flex;
  justify-content: space-between;
  padding: var(--space-sm) 0;
  border-bottom: 1px solid var(--color-border);
}

.confirm-row:last-child {
  border-bottom: none;
}

.confirm-row span:first-child {
  font-weight: 600;
  color: var(--color-charcoal-light);
}

.btn-secondary {
  padding: var(--space-sm) var(--space-md);
  background-color: transparent;
  border: 1px solid var(--color-border);
  color: var(--color-text-secondary);
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 600;
  border-radius: var(--radius-md);
  cursor: pointer;
  margin-top: var(--space-lg);
}

.btn-secondary:hover {
  background-color: #F2EBE3;
  color: var(--color-charcoal);
}

.btn-secondary:focus {
  outline: none;
  box-shadow: 0 0 0 3px rgba(194, 124, 90, 0.2);
}

.demo-disclosure {
  text-align: center;
  padding: var(--space-lg) 0;
  color: var(--color-text-secondary);
  font-size: 14px;
  border-top: 1px solid var(--color-border);
  margin-top: var(--space-xxl);
}

@media (max-width: 1024px) {
  .editorial-hero {
    grid-template-columns: 1fr;
    min-height: auto;
  }

  .pottery-illustration {
    height: 240px;
  }

  .catalogue {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .masthead h1 {
    font-size: 28px;
  }

  .hero-content h2 {
    font-size: 28px;
  }

  .catalogue {
    grid-template-columns: 1fr;
  }

  .editorial-hero {
    padding: var(--space-lg);
  }

  main {
    padding: 0 var(--space-md);
  }
}

@media (max-width: 320px) {
  .masthead {
    padding: var(--space-md);
  }

  .masthead h1 {
    font-size: 24px;
  }

  .subtitle {
    font-size: 16px;
  }

  .hero-content h2 {
    font-size: 24px;
  }

  .editorial-hero {
    padding: var(--space-md);
    gap: var(--space-md);
  }

  .pottery-illustration {
    height: 180px;
  }

  .catalogue-card {
    padding: var(--space-md);
  }

  .booking-section, #confirmation {
    padding: var(--space-md);
  }

  main {
    padding: 0 var(--space-sm);
  }
}
.btn-primary,
.btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

#confirmation .btn-secondary {
  margin-top: var(--space-lg);
}

[hidden],
[style*="display: none"] {
  display: none !important;
}

@media (prefers-reduced-motion: reduce) {
  .catalogue-card,
  .btn-detail {
    transition: none;
  }

  #booking-section {
    scroll-behavior: auto;
  }
}

@media (max-width: 390px) {
  .editorial-hero {
    padding: var(--space-md);
    gap: var(--space-md);
  }

  .hero-content h2 {
    font-size: 24px;
  }

  .pottery-illustration {
    height: 160px;
  }

  .catalogue-card {
    padding: var(--space-md);
  }

  .card-meta {
    flex-wrap: wrap;
  }

  #booking-section,
  #confirmation {
    padding: var(--space-md);
  }

  main {
    padding: 0 var(--space-sm);
  }
}

@media (max-width: 320px) {
  .masthead h1 {
    font-size: 24px;
  }

  .hero-content h2 {
    font-size: 24px;
  }

  .pottery-illustration {
    height: 140px;
  }

  .btn-primary,
  .btn-detail {
    width: 100%;
  }
}

app.js:
const CLASSES = [
  {
    id: "class-1",
    title: "도자기 첫 잔",
    category: "도자기",
    price: 55000,
    duration: "90분",
    capacity: 6,
    description: "내 손으로 만드는 첫 번째 찻잔. 성형부터 유약 발림까지 기본을 배워보세요."
  },
  {
    id: "class-2",
    title: "가죽 카드 지갑",
    category: "가죽",
    price: 48000,
    duration: "120분",
    capacity: 5,
    description: "소형 카드와 명함을 수납할 수 있는 심플한 지갑을 제작합니다."
  },
  {
    id: "class-3",
    title: "나무 트레이",
    category: "우드",
    price: 62000,
    duration: "150분",
    capacity: 4,
    description: "원목을 다듬고 손질하여 식탁 위에 놓을 예쁜 트레이를 완성합니다."
  }
];

const STORAGE_KEY = "samkill-ui-booking-demo";

let state = {
  classes: CLASSES,
  selectedClassId: null,
  searchQuery: "",
  confirmation: null
};

function loadState() {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (parsed && parsed.confirmation) {
        state.confirmation = parsed.confirmation;
      }
    }
  } catch (e) {
    console.error("Failed to load state", e);
  }
}

function saveState() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({
      confirmation: state.confirmation
    }));
  } catch (e) {
    console.error("Failed to save state", e);
  }
}

function renderCatalogue() {
  const container = document.getElementById("catalogue-list");
  if (!container) return;

  const filtered = state.classes.filter(cls =>
    cls.title.includes(state.searchQuery) ||
    cls.category.includes(state.searchQuery)
  );

  container.innerHTML = "";

  if (filtered.length === 0) {
    const emptyMsg = document.createElement("p");
    emptyMsg.className = "empty-state";
    emptyMsg.textContent = "검색 결과가 없습니다.";
    container.appendChild(emptyMsg);
    return;
  }

  filtered.forEach(cls => {
    const card = document.createElement("article");
    card.className = "catalogue-card";
    card.dataset.id = cls.id;

    const illustration = document.createElement("div");
    illustration.className = "card-illustration";

    const title = document.createElement("h3");
    title.textContent = cls.title;

    const category = document.createElement("span");
    category.className = "card-category";
    category.textContent = cls.category;

    const desc = document.createElement("p");
    desc.className = "card-description";
    desc.textContent = cls.description;

    const meta = document.createElement("div");
    meta.className = "card-meta";
    const duration = document.createElement("span");
    duration.textContent = cls.duration;
    const capacity = document.createElement("span");
    capacity.textContent = `정원 ${cls.capacity}명`;

    const price = document.createElement("div");
    price.className = "card-price";
    price.textContent = `${cls.price.toLocaleString()}원`;

    const btn = document.createElement("button");
    btn.className = "btn-detail";
    btn.textContent = "상세";
    btn.dataset.id = cls.id;

    card.append(illustration, title, category, desc, meta, price, btn);
    container.appendChild(card);
  });
}

function renderSelectedClass() {
  const section = document.getElementById("booking-section");
  const info = document.getElementById("selected-class-info");
  if (!section || !info) return;

  if (!state.selectedClassId) {
    section.style.display = "none";
    return;
  }

  const cls = state.classes.find(c => c.id === state.selectedClassId);
  if (!cls) {
    section.style.display = "none";
    return;
  }

  info.innerHTML = "";
  const title = document.createElement("h3");
  title.textContent = cls.title;
  const cat = document.createElement("p");
  cat.textContent = `${cls.category} | ${cls.duration} | 정원 ${cls.capacity}명`;
  const desc = document.createElement("p");
  desc.textContent = cls.description;
  const price = document.createElement("p");
  price.className = "selected-price";
  price.textContent = `${cls.price.toLocaleString()}원`;

  info.append(title, cat, desc, price);
  section.style.display = "block";
}

function renderConfirmation() {
  const section = document.getElementById("confirmation");
  const details = document.getElementById("confirmation-details");
  if (!section || !details) return;

  if (!state.confirmation) {
    section.style.display = "none";
    return;
  }

  details.innerHTML = "";
  const title = document.createElement("h3");
  title.textContent = state.confirmation.className;
  const rows = [
    { label: "예약자", value: state.confirmation.guest },
    { label: "방문일", value: state.confirmation.date },
    { label: "시간", value: state.confirmation.slot }
  ];

  rows.forEach(row => {
    const rowDiv = document.createElement("div");
    rowDiv.className = "confirm-row";
    const lbl = document.createElement("span");
    lbl.textContent = row.label + ": ";
    const val = document.createElement("span");
    val.textContent = row.value;
    rowDiv.append(lbl, val);
    details.appendChild(rowDiv);
  });

  section.style.display = "block";
}

function initRender() {
  loadState();
  renderCatalogue();
  renderSelectedClass();
  renderConfirmation();
}
document.getElementById("search").addEventListener("input", (e) => {
  state.searchQuery = e.target.value;
  renderCatalogue();
});

document.getElementById("catalogue-list").addEventListener("click", (e) => {
  const btn = e.target.closest(".btn-detail");
  if (!btn) return;

  state.selectedClassId = btn.dataset.id;
  renderSelectedClass();
  document.getElementById("booking-section").scrollIntoView({ behavior: "smooth" });
});
document.getElementById("booking-form").addEventListener("submit", (e) => {
  e.preventDefault();
  const guest = document.getElementById("guest");
  const date = document.getElementById("date");
  const slot = document.getElementById("slot");
  if (!guest.value || !date.value || !slot.value) return;

  state.confirmation = {
    classId: state.selectedClassId,
    className: state.classes.find(c => c.id === state.selectedClassId)?.title,
    guest: guest.value,
    date: date.value,
    slot: slot.value
  };
  saveState();
  renderConfirmation();
  document.getElementById("booking-section").style.display = "none";
});

document.getElementById("cancel-booking").addEventListener("click", () => {
  state.confirmation = null;
  saveState();
  renderConfirmation();
});

initRender();
